package com.proxy.gateway

import java.io.{File, InputStream, OutputStream}
import java.net.{ServerSocket, Socket, URI}
import java.nio.file.{Files, Path, Paths}
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

sealed trait Role
case object Admin extends Role
case object User extends Role
case object Guest extends Role

case class Session(userId: String, role: Role, token: String)

object AccessControl {
  private val sessions = mutable.Map[String, Session]()

  def createSession(userId: String, role: Role): Session = {
    val token = java.util.UUID.randomUUID().toString
    val session = Session(userId, role, token)
    sessions.put(token, session)
    session
  }

  def getSession(token: String): Option[Session] = sessions.get(token)

  def hasDirectoryAccess(session: Session, path: String): Boolean = {
    session.role match {
      case Admin => true
      case User => !path.contains("/admin/") && !path.contains("/internal/")
      case Guest => path.startsWith("/public/")
    }
  }
}

object PathNormalizer {
  // Normalize path to prevent traversal attacks
  def normalize(rawPath: String): String = {
    val decoded = java.net.URLDecoder.decode(rawPath, "UTF-8")
    val path = Paths.get(decoded).normalize().toString
    // Remove any leading dots or double-dots
    path.replaceAll("\\.\\./", "").replaceAll("^\\.+", "")
  }

  def isDirectoryRequest(path: String): Boolean = {
    path.endsWith("/") || !path.contains(".")
  }
}

class ProxyHandler(baseDir: String) {
  private val LISTING_TEMPLATE = """<html><body><h2>Index of %s</h2><ul>%s</ul></body></html>"""

  def handleRequest(method: String, rawPath: String, headers: Map[String, String]): (Int, String, String) = {
    val token = headers.getOrElse("X-Auth-Token", "")
    val sessionOpt = AccessControl.getSession(token)

    sessionOpt match {
      case None => (401, "text/plain", "Unauthorized")
      case Some(session) =>
        val normalizedPath = PathNormalizer.normalize(rawPath)

        if (!AccessControl.hasDirectoryAccess(session, normalizedPath)) {
          (403, "text/plain", "Forbidden")
        } else if (PathNormalizer.isDirectoryRequest(normalizedPath)) {
          serveDirectoryListing(normalizedPath, session)
        } else {
          serveFile(normalizedPath)
        }
    }
  }

  private def serveDirectoryListing(path: String, session: Session): (Int, String, String) = {
    val resolvedPath = resolveToFilesystem(path)
    val dir = new File(resolvedPath)

    if (!dir.exists() || !dir.isDirectory) {
      (404, "text/plain", "Not Found")
    } else {
      val canonicalBase = new File(baseDir).getCanonicalPath
      if (!dir.getCanonicalPath.startsWith(canonicalBase)) {
        return (403, "text/plain", "Forbidden")
      }

      val entries = dir.listFiles()
      val filteredEntries = filterEntriesByRole(entries, session, path)
      val listing = filteredEntries.map { f =>
        val name = if (f.isDirectory) f.getName + "/" else f.getName
        val escapedName = name.replace("&", "&amp;").replace("<", "&lt;").replace("\"", "&quot;")
        s"""<li><a href="$escapedName">$escapedName</a></li>"""
      }.mkString("\n")

      (200, "text/html", LISTING_TEMPLATE.format(path.replace("<", "&lt;"), listing))
    }
  }

  private def filterEntriesByRole(entries: Array[File], session: Session, basePath: String): Array[File] = {
    if (entries == null) return Array.empty

    val normalizedBase = if (basePath.endsWith("/")) basePath else basePath + "/"

    session.role match {
      case Admin => entries.filterNot(f => f.getName.startsWith("."))
      case User => 
        entries.filterNot { f =>
          val childPath = normalizedBase + f.getName + (if (f.isDirectory) "/" else "")
          childPath.contains("/admin/") || childPath.contains("/internal/") || f.getName.startsWith(".")
        }
      case Guest =>
        entries.filter { f =>
          val childPath = normalizedBase + f.getName + (if (f.isDirectory) "/" else "")
          isPublicEntry(childPath) && !f.getName.startsWith(".")
        }
    }
  }

  private def isPublicEntry(path: String): Boolean = {
    path.startsWith("/public/") || path == "/public"
  }

  private def resolveToFilesystem(path: String): String = {
    val cleanPath = if (path.startsWith("/")) path.substring(1) else path
    val resolved = Paths.get(baseDir, cleanPath).normalize().toString
    resolved
  }

  private def serveFile(path: String): (Int, String, String) = {
    val resolvedPath = resolveToFilesystem(path)
    val file = new File(resolvedPath)
    val canonicalBase = new File(baseDir).getCanonicalPath

    if (!file.getCanonicalPath.startsWith(canonicalBase)) {
      (403, "text/plain", "Forbidden")
    } else if (!file.exists() || file.isDirectory) {
      (404, "text/plain", "Not Found")
    } else {
      val content = new String(Files.readAllBytes(file.toPath))
      val contentType = guessContentType(path)
      (200, contentType, content)
    }
  }

  private def guessContentType(path: String): String = {
    if (path.endsWith(".html")) "text/html"
    else if (path.endsWith(".json")) "application/json"
    else if (path.endsWith(".css")) "text/css"
    else if (path.endsWith(".js")) "application/javascript"
    else "application/octet-stream"
  }
}

object ProxyServer extends App {
  val baseDir = sys.env.getOrElse("PROXY_BASE_DIR", "/var/www")
  val port = sys.env.getOrElse("PROXY_PORT", "8080").toInt
  val handler = new ProxyHandler(baseDir)

  val serverSocket = new ServerSocket(port)
  println(s"Proxy server listening on port $port")

  while (true) {
    val clientSocket = serverSocket.accept()
    new Thread(() => handleClient(clientSocket)).start()
  }

  def handleClient(socket: Socket): Unit = {
    Try {
      val input = scala.io.Source.fromInputStream(socket.getInputStream)
      val lines = input.getLines().takeWhile(_.nonEmpty).toList

      if (lines.nonEmpty) {
        val requestLine = lines.head.split(" ")
        val method = requestLine(0)
        val path = requestLine(1)
        val headers = lines.tail.map { line =>
          val parts = line.split(": ", 2)
          parts(0) -> parts(1)
        }.toMap

        val (status, contentType, body) = handler.handleRequest(method, path, headers)
        val response = s"HTTP/1.1 $status OK\r\nContent-Type: $contentType\r\nContent-Length: ${body.length}\r\n\r\n$body"
        socket.getOutputStream.write(response.getBytes)
      }
    }
    socket.close()
  }
}
